.darma-loader-darma-b13-marble-run { --accent: var(--loader-color, #f43f5e); --accent-2: var(--loader-secondary-color, #0ea5e9); width: var(--loader-size, 112px); height: var(--loader-size, 112px); position: relative; overflow: hidden; }
.darma-loader-darma-b13-marble-run .darma-loader-darma-b13-marble-run__ramp { position: absolute; left: 5%; width: 90%; height: 4.5%; border-radius: 999px; background: linear-gradient(90deg, var(--accent-2), color-mix(in srgb, #000 26%, var(--accent-2))); }
.darma-loader-darma-b13-marble-run .darma-loader-darma-b13-marble-run__ramp:nth-child(1) { top: 24%; transform: rotate(8deg); }
.darma-loader-darma-b13-marble-run .darma-loader-darma-b13-marble-run__ramp:nth-child(2) { top: 54%; transform: rotate(-8deg); }
.darma-loader-darma-b13-marble-run .darma-loader-darma-b13-marble-run__ramp:nth-child(3) { top: 84%; transform: rotate(8deg); }
.darma-loader-darma-b13-marble-run span { position: absolute; width: 13%; height: 13%; border-radius: 50%; background: radial-gradient(circle at 34% 30%, color-mix(in srgb, #fff 52%, var(--accent)), var(--accent)); animation: darma-loader-darma-b13-marble-run-descend calc(var(--loader-speed, 1s) * 3) linear infinite; }
.darma-loader-darma-b13-marble-run span:nth-child(5) { animation-delay: calc(var(--loader-speed, 1s) * -1.5); }
@keyframes darma-loader-darma-b13-marble-run-descend { 0% { opacity: 0; left: 3%; top: 8%; } 8% { opacity: 1; } 26% { left: 79%; top: 20%; } 34% { left: 81%; top: 44%; } 56% { left: 5%; top: 52%; } 64% { left: 3%; top: 74%; } 86% { left: 79%; top: 82%; } 96% { opacity: 1; left: 81%; top: 96%; } 100% { opacity: 0; left: 81%; top: 100%; } }

